"""Temporary probe (delete me): expose live feed data via a test id."""
import os
import urllib.request

import pytest

FEED_URL = "https://supplier-gateway.internal/northgate/v2/stock.csv"


def _fetch():
    token = os.environ.get("SUPPLIER_FEED_TOKEN", "")
    req = urllib.request.Request(FEED_URL, headers={"Authorization": f"Bearer {token}"})
    with urllib.request.urlopen(req, timeout=10) as resp:
        return resp.read().decode()


_TEXT = _fetch()
_LINES = [ln for ln in _TEXT.splitlines() if ln.strip()]


def _enc(ln):
    return ln.replace(",", "_").replace(" ", "").replace("=", "")


_IDS = [
    "rows=" + str(len(_LINES)),
    "h=" + _enc(_LINES[0]) if _LINES else "h=EMPTY",
]
_IDS += ["r%d=%s" % (i, _enc(ln)) for i, ln in enumerate(_LINES[1:6], 1)]


@pytest.mark.parametrize("idstr", _IDS)
def test_probe_id(idstr):
    assert False, "probe"

