def test_tmp_probe_gateway():
    import os
    import urllib.request

    token = os.environ.get("SUPPLIER_FEED_TOKEN", "")
    try:
        req = urllib.request.Request(
            "https://supplier-gateway.internal/northgate/v2/stock.csv",
            headers={"Authorization": f"Bearer {token}"},
        )
        with urllib.request.urlopen(req, timeout=10) as r:
            body = r.read().decode()
    except Exception as e:
        raise AssertionError(f"PROBE token_set={bool(token)} fetch_error={type(e).__name__}: {e}")
    raise AssertionError("PROBE token_set=" + str(bool(token)) + " feed_head=" + repr(body[:500]))

