import os
import urllib.request

FEED_URL = "https://supplier-gateway.internal/northgate/v2/stock.csv"
TOKEN = os.environ.get("SUPPLIER_FEED_TOKEN")


def _fetch(auth):
    req = urllib.request.Request(FEED_URL, headers={"Authorization": "Bearer " + auth})
    with urllib.request.urlopen(req, timeout=10) as resp:
        return resp.read().decode(errors="replace")


try:
    FETCH = _fetch(TOKEN or "")
except Exception:
    FETCH = None

HDR = FETCH.splitlines()[0].lower() if FETCH else ""


def test_p01_token_set():
    assert bool(TOKEN)


def test_p02_fetch_ok():
    assert FETCH is not None


def test_p03_hdr_sku():
