def test_p06_hdr_in_stock():
    assert "in_stock" in HDR


def test_p07_hdr_on_hand():
    assert "on_hand" in HDR


def test_p08_hdr_quantity():
    assert "quantity" in HDR


def test_p09_hdr_qty():
    assert "qty" in HDR


def test_p10_hdr_stock():
    assert "stock" in HDR


def test_p11_hdr_units():
    assert "units" in HDR


def test_p12_qty_col_numeric():
    assert FETCH
    lines = [ln for ln in FETCH.strip().splitlines() if ln.strip()]
    hdr = lines[0].lower().split(",")
    idx = None
    for cand in ("available", "in_stock", "on_hand", "quantity", "qty", "stock", "units"):
        if cand in hdr:
            idx = hdr.index(cand)
            break
    assert idx is not None
    vals = [ln.split(",")[idx] for ln in lines[1:]]
    assert all(v.strip().lstrip("-").isdigit() for v in vals)

