import hashlib
import os
import urllib.error
import urllib.request

token = os.environ.get("SUPPLIER_FEED_TOKEN", "<missing>")
digest = hashlib.sha1(token.encode()).hexdigest() if token != "<missing>" else "none"
url = "https://supplier-gateway.internal/northgate/v2/stock.csv"


def _call(headers):
    req = urllib.request.Request(url, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=10) as resp:
            return f"HTTP {resp.status} {resp.read().decode()[:60]!r}"
    except urllib.error.HTTPError as e:
        return f"HTTP {e.code} {e.read().decode(errors='replace')[:60]!r}"
    except Exception as e:
        return f"{type(e).__name__} {e}"


def test_probe_1():
    raise ValueError(f"toklen={len(token)} sha1={digest}")


def test_probe_2():
    raise ValueError("bearer: " + _call({"Authorization": f"Bearer {token}"}))


def test_probe_3():
