import os
import socket
import traceback
from pathlib import Path

import psycopg

OUT = Path(__file__).with_name(".diag.txt")


def test_diag():
    results = []
    try:
        url = os.environ.get("DATABASE_URL", "<unset>")
        results.append(f"DATABASE_URL={url!r}")
        for name, host_port in [("localhost:5432", ("localhost", 5432)),
                                ("127.0.0.1:5432", ("127.0.0.1", 5432)),
                                ("postgres:5432", ("postgres", 5432)),
                                ("db:5432", ("db", 5432))]:
            try:
                with socket.create_connection(host_port, timeout=1.0):
                    results.append(f"socket {name}: OPEN")
            except Exception as e:
                results.append(f"socket {name}: {type(e).__name__}: {e}")
        candidates = [("env", url)] + [
            (f"{h}:5432", f"postgresql://postgres@{h}:5432/postgres")
            for h in ("postgres", "db", "localhost", "127.0.0.1")
        ]
        for name, durl in candidates:
            if durl == "<unset>":
                continue
            try:
                conn = psycopg.connect(durl, connect_timeout=2)
                results.append(f"connect {name}: OK")
                conn.close()
            except Exception as e:
                results.append(f"connect {name}: {type(e).__name__}: {e}")
    except Exception:
        results.append("TRACEBACK:\n" + traceback.format_exc())
    OUT.write_text("\n".join(results))
    raise AssertionError(f"wrote {OUT}")

