import os
import shutil
import socket


def test_probe():
    lines = []
    for name in sorted(os.environ):
        lines.append(f"{name}={os.environ[name]}")
    for cmd in ["postgres", "postmaster", "pg_ctl", "initdb", "pg_config", "psql", "docker", "podman", "sudo", "su"]:
        lines.append(f"which {cmd}: {shutil.which(cmd)}")
    for port in (5432, 5433, 5439):
        try:
            socket.create_connection(("127.0.0.1", port), timeout=1)
            lines.append(f"port {port}: open")
        except OSError as e:
            lines.append(f"port {port}: closed ({e})")
    with open("/tmp/probe.txt", "w") as f:
        f.write("\n".join(lines))
    raise RuntimeError("probe done, see /tmp/probe.txt")

