def test_probe():
    w = {c: shutil.which(c) for c in ("postgres", "pg_ctl", "initdb", "psql", "docker")}
    try:
        socket.create_connection(("127.0.0.1", 5432), timeout=1)
        p = "OPEN"
    except OSError:
        p = "closed"
    paths = [d for d in (
        "/usr/lib/postgresql/16/bin/postgres",
        "/usr/pgsql-16/bin/postgres",
        "/usr/local/pgsql/bin/postgres",
        "/usr/bin/postgres",
        "/var/lib/postgresql",
    ) if os.path.exists(d)]
    raise ModuleNotFoundError(
        f"url={os.environ.get('DATABASE_URL')} p={p} uid={os.getuid()} w={w} paths={paths}"
    )

