import os
import shutil
import socket
import subprocess


def test_probe():
    dburl = os.environ.get("DATABASE_URL")
    progs = {name: shutil.which(name) for name in ("postgres", "pg_ctl", "initdb", "psql", "docker", "pg_ctlcluster", "service")}
    try:
        s = socket.create_connection(("127.0.0.1", 5432), timeout=2)
        conn_msg = "tcp-ok"
        s.close()
    except Exception as e:
        conn_msg = f"tcp-fail:{type(e).__name__}:{e}"
    try:
        s = socket.create_connection(("127.0.0.1", 5433), timeout=1)
        conn2 = "tcp5433-ok"
        s.close()
    except Exception as e:
        conn2 = f"tcp5433-fail:{type(e).__name__}"
    ls = subprocess.run(["ls", "/var/lib/postgresql", "/usr/lib/postgresql"], capture_output=True, text=True)
    raise AssertionError(
        f"DBURL={dburl!r} which={progs} conn={conn_msg} {conn2} ls_out={ls.stdout!r} ls_err={ls.stderr!r}"
    )

