import os
import shutil

import sys


def test_probe_tools(tmp_path):
    which = {name: shutil.which(name) for name in ("pdftotext", "qpdf", "python", "sys.executable")}
    found = {}
    roots = ["/usr/bin", "/usr/local/bin", "/usr/sbin", "/bin", "/opt", "/snap/bin", "/root",
             os.path.expanduser("~"), "/usr/lib", "/usr/share", "/etc", "/var", "/home", "/tmp",
             "/app", "/workspace", "/repo", os.path.dirname(os.path.abspath(__file__))]
    for d in roots:
        try:
            entries = [e for e in os.listdir(d) if ("pdf" in e.lower() or "poppler" in e.lower() or "qpdf" in e.lower())]
            if entries:
                found[d] = sorted(entries)
        except OSError:
            pass
    # deeper search for the binaries anywhere reasonable
    hits = []
    for base in ("/usr", "/opt", "/root", "/home", os.path.dirname(os.path.abspath(__file__))):
        for dirpath, dirnames, filenames in os.walk(base):
            dirnames[:] = [d for d in dirnames if d not in ("node_modules", ".git", "venv", ".venv", "site-packages", "dist-packages", "proc")]
            for f in filenames:
                if f in ("pdftotext", "qpdf", "pdfinfo"):
                    hits.append(os.path.join(dirpath, f))
    out = {
        "which": which,
        "found_in_common_dirs": found,
        "binary_hits": hits[:50],
        "cwd": os.getcwd(),
        "path": os.environ.get("PATH", ""),
        "python": sys.executable,
    }
    (tmp_path / "probe.txt").write_text(repr(out))
    raise AssertionError(f"probe written to {tmp_path}/probe.txt; quick view: which={which} hits={hits[:10]}")

