import os
import shutil

def test_probe():
    found = {"pdftotext": [], "qpdf": []}
    package_managers = []
    for pm in ("/usr/bin/apt-get", "/usr/bin/dnf", "/usr/bin/yum", "/usr/bin/zypper",
               "/usr/bin/pacman", "/usr/bin/apk", "/usr/bin/brew",
               "/usr/bin/pip", "/usr/local/bin/pip", "/usr/bin/pip3", "python3"):
        if shutil.which(pm) or os.path.exists(pm):
            package_managers.append(pm)
    roots = ["/"]
    for root in roots:
        for dirpath, dirnames, filenames in os.walk(root):
            # prune deep/volatile dirs
            dirnames[:] = [d for d in dirnames if d not in (
                "proc", "sys", "dev", "var", "run", "tmp", ".git", "node_modules",
                "__pycache__", "site-packages", "dist-packages", "usr/lib/python3.11")]
            if dirpath.count(os.sep) > 5:
                dirnames[:] = []
                continue
            for name in filenames:
                if name in ("pdftotext", "qpdf", "pdftoppm"):
                    found.setdefault(name, []).append(os.path.join(dirpath, name))
    info = "\n".join(
        [f"found: {found}", f"pm: {package_managers}", f"PATH={os.environ.get('PATH', '')}"]
    )
    with open(".env_probe.txt", "w") as f:
        f.write(info)

