def test_probe():
    import os
    import shutil
    import subprocess

    osid = "?"
    try:
        with open("/etc/os-release") as f:
            for line in f:
                if line.startswith("ID="):
                    osid = line.strip()
    except OSError:
        pass
    pm = [p for p in ("apt-get", "dnf", "yum", "zypper", "pacman", "apk", "brew") if shutil.which(p)]
    uid = "?"
    try:
        uid = subprocess.run(["id", "-u"], capture_output=True, text=True).stdout.strip()
    except Exception:
        pass
    have = [p for p in ("pdftotext", "qpdf") if shutil.which(p)]
    raise AssertionError(f"os={osid} uid={uid} pm={pm} have={have}")

